window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-445ff1a7f8639782"]={"versions": [{"id": "FIG-445ff1a7f8639782", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Teilablaufs „Compute offset“ innerhalb des E2E-Profils 6 (AUTOSAR Classic &amp; Adaptive Platform, Spezifikation <code>AUTOSAR_PRS_E2EProtocol</code>). Der Ablauf ist gemeinsamen Kontexten der E2E-Funktionen <code>E2E_P06Protect()</code>, <code>E2E_P06Check()</code> und <code>E2E_P06Forward()</code> zugeordnet.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitätskontexte (Aufrufende Funktionen / Scope)</strong>:\n<ul class=\"fig-list\"><li><code>E2E_P06Protect()</code>\n</li><li><code>E2E_P06Check()</code>\n</li><li><code>E2E_P06Forward()</code>\n</li></ul>\n</li><li><strong>Aktionen &amp; Datenstrukturen</strong>:\n<ul class=\"fig-list\"><li>Aktion <code>Offset = Config-&gt;Offset / 8</code>\n</li><li>Eingangsparameter: <code>Config-&gt;Offset</code> (Konfigurationsstruktur-Element, Bit-Offset)\n</li><li>Lokale Ergebnisvariable: <code>Offset</code> (Datentyp <code>uint16</code>, Einheit Byte, erläutert via Kommentar/Note: „compute local variable uint16 Offset, which is in [byte]“)\n</li></ul>\n</li><li><strong>Knotenelemente</strong>:\n<ul class=\"fig-list\"><li>Startknoten (Initial Node)\n</li><li>Endknoten (Activity Final Node)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt über den Startknoten (Initial Node) bei Ausführung des Unterschritts „Compute offset“ in <code>E2E_P06Protect()</code>, <code>E2E_P06Check()</code> oder <code>E2E_P06Forward()</code>.\n</li><li>Ausführung der Berechnungsaktion <code>Offset = Config-&gt;Offset / 8</code>, welche den konfigurierten Bit-Offset in einen Byte-Offset umrechnet und in der lokalen Variablen <code>Offset</code> (<code>uint16</code>) ablegt.\n</li><li>Übergang in den Endknoten (Activity Final Node) und Beendigung des Schritts.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Vorschrift gemäß PRS_E2E_00470 für E2E-Profil 6:</p>\n<ul class=\"fig-list\"><li>Der Byte-Offset muss deterministisch durch Division des Konfigurationsparameters <code>Config-&gt;Offset</code> durch 8 ermittelt werden.\n</li><li>Die berechnete Variable <code>Offset</code> ist als vorzeichenloser 16-Bit-Ganzzahlwert (<code>uint16</code>) vorzuhalten und dient nachfolgenden Berechnungen/Prüfungen (z. B. Positionierung der Header-Felder CRC und Sequenzzähler im Datenpuffer) als Byte-Basis.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9cda49b5a27377e3", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Teilablaufs „Compute offset“ innerhalb des E2E-Profils 6 (AUTOSAR Classic &amp; Adaptive Platform, Spezifikation <code>AUTOSAR_PRS_E2EProtocol</code>). Der Ablauf ist gemeinsamen Kontexten der E2E-Funktionen <code>E2E_P06Protect()</code>, <code>E2E_P06Check()</code> und <code>E2E_P06Forward()</code> zugeordnet.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitätskontexte (Aufrufende Funktionen / Scope)</strong>:\n<ul class=\"fig-list\"><li><code>E2E_P06Protect()</code>\n</li><li><code>E2E_P06Check()</code>\n</li><li><code>E2E_P06Forward()</code>\n</li></ul>\n</li><li><strong>Aktionen &amp; Datenstrukturen</strong>:\n<ul class=\"fig-list\"><li>Aktion <code>Offset = Config-&gt;Offset / 8</code>\n</li><li>Eingangsparameter: <code>Config-&gt;Offset</code> (Konfigurationsstruktur-Element, Bit-Offset)\n</li><li>Lokale Ergebnisvariable: <code>Offset</code> (Datentyp <code>uint16</code>, Einheit Byte, erläutert via Kommentar/Note: „compute local variable uint16 Offset, which is in [byte]“)\n</li></ul>\n</li><li><strong>Knotenelemente</strong>:\n<ul class=\"fig-list\"><li>Startknoten (Initial Node)\n</li><li>Endknoten (Activity Final Node)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt über den Startknoten (Initial Node) bei Ausführung des Unterschritts „Compute offset“ in <code>E2E_P06Protect()</code>, <code>E2E_P06Check()</code> oder <code>E2E_P06Forward()</code>.\n</li><li>Ausführung der Berechnungsaktion <code>Offset = Config-&gt;Offset / 8</code>, welche den konfigurierten Bit-Offset in einen Byte-Offset umrechnet und in der lokalen Variablen <code>Offset</code> (<code>uint16</code>) ablegt.\n</li><li>Übergang in den Endknoten (Activity Final Node) und Beendigung des Schritts.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Vorschrift gemäß PRS_E2E_00470 für E2E-Profil 6:</p>\n<ul class=\"fig-list\"><li>Der Byte-Offset muss deterministisch durch Division des Konfigurationsparameters <code>Config-&gt;Offset</code> durch 8 ermittelt werden.\n</li><li>Die berechnete Variable <code>Offset</code> ist als vorzeichenloser 16-Bit-Ganzzahlwert (<code>uint16</code>) vorzuhalten und dient nachfolgenden Berechnungen/Prüfungen (z. B. Positionierung der Header-Felder CRC und Sequenzzähler im Datenpuffer) als Byte-Basis.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-445ff1a7f8639782", "to": "FIG-9cda49b5a27377e3", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
